window.VLXT_THPTQG_PRELOADED_EXAMS = {"1":{"examNumber":1,"examId":"THPTQG-2026-DE01","title":"Đề Thi Thử THPTQG 2026 – Đề số 01 (Khảo sát năng lực chuẩn Bộ)","purpose":"KHAO_SAT_FREE","purposeLabel":"🎯 Test Điểm Thi THPTQG · Khảo Sát Miễn Phí","durationMinutes":50,"questions":[{"num":1,"id":"VLXT-ST220-C2-CD07-LT02","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD07 – Quá trình đẳng nhiệt & Định luật Boyle","baiHoc":"B11. ĐỊNH LUẬT BOYLE – QUÁ TRÌNH ĐẲNG NHIỆT","level":"TH","modelId":"MH-TN220-C2-30","hinhAnh":"assets/images/staging-220/q220_lt_004.png","deBaiChung":"","question":"Trong thí nghiệm kiểm chứng lại định luật Boyle, việc dịch chuyển pit-tông từ từ giúp đảm bảo điều kiện gì?\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN220-C2-30\"></div>","explain":"Thí nghiệm kiểm chứng định luật Boyle khảo sát quá trình biến đổi <strong>đẳng nhiệt</strong> ($T = \\text{hằng số}$). Dịch chuyển pit-tông rất từ từ giúp khối khí kịp trao đổi nhiệt với môi trường xung quanh để <strong>nhiệt độ khí trong xi lanh không đổi</strong>. Vậy chọn <strong>B</strong>.","options":["Khối lượng khí trong xi lanh không đổi.","Nhiệt độ khí trong xi lanh không đổi.","Thể tích khí trong xi lanh không đổi.","Áp suất khí trong xi lanh không đổi."],"answer":1,"correctLetter":"B"},{"num":2,"id":"VLXT-PT-P024-Q26","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD02 – Sự chuyển thể (Nóng chảy, Đông đặc, Hóa hơi, Sôi, Ngưng tụ)","baiHoc":"B2. LỰC LIÊN KẾT VÀ SỰ CHUYỂN THỂ CỦA CHẤT","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Quá trình chuyển từ thể khí sang thể lỏng của các chất được gọi là","explain":"Quá trình chuyển từ thể khí sang thể lỏng là sự ngưng tụ.","options":["sự đông đặc.","sự hóa hơi.","sự nóng chảy.","sự ngưng tụ."],"answer":3,"correctLetter":"D"},{"num":3,"id":"VLXT-T1-L01-Q45","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD03 – Nhiệt độ, Sự truyền nhiệt, Nhiệt kế & Thang đo nhiệt độ","baiHoc":"B3. NHIỆT ĐỘ – THANG NHIỆT ĐỘ – NHIỆT KẾ","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Thao tác nào sau đây chưa chính xác khi dùng nhiệt kế thuỷ ngân?","explain":"Nắm chặt bầu nhiệt kế truyền nhiệt từ tay làm sai lệch kết quả, và thời gian kẹp nách cần tối thiểu 3-5 phút để cân bằng nhiệt; đọc sau 30 giây là chưa đủ thời gian.","options":["Vẩy mạnh nhiệt kế trước khi đo.","Dùng tay nắm chặt bầu nhiệt kế một lúc rồi mới đo.","Đưa nhiệt kế kẹp nách ra đọc sau $30\\text{ s}$.","Cả hai đáp án B và C."],"answer":3,"correctLetter":"D"},{"num":4,"id":"VLXT-PT-DE_15-P1-Q04","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD04 – Nhiệt dung riêng, Nhiệt nóng chảy riêng, Hóa hơi riêng & Thí nghiệm","baiHoc":"B4. NHIỆT DUNG RIÊNG - NÓNG CHẢY RIÊNG - HOÁ HƠI RIÊNG","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Phát biểu nào sau đây là đúng?","explain":"Từ công thức $Q = mc\\Delta t \\Rightarrow \\Delta t = \\frac{Q}{mc}$. Chất có nhiệt dung riêng $c$ nhỏ thì với cùng nhiệt lượng trao đổi, độ biến thiên nhiệt độ $\\Delta t$ sẽ lớn, nghĩa là vật dễ nóng lên khi thu nhiệt và nhanh nguội đi khi tỏa nhiệt.","options":["Vật làm bằng chất có nhiệt dung riêng nhỏ thì vật đó dễ nóng lên và nhanh nguội đi.","Vật làm bằng chất có nhiệt dung riêng nhỏ thì vật đó dễ nóng lên và lâu nguội đi.","Vật làm bằng chất có nhiệt dung riêng nhỏ thì vật đó khó nóng lên và nhanh nguội đi.","Vật làm bằng chất có nhiệt dung riêng nhỏ thì vật đó khó nóng lên và lâu nguội đi."],"answer":0,"correctLetter":"A"},{"num":5,"id":"VLXT-PT-DE_01-P1-Q01","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD05 – Nội năng, Định luật I NĐLH (ΔU = A + Q) & Động cơ nhiệt","baiHoc":"B5. NỘI NĂNG – ĐỊNH LUẬT I NHIỆT ĐỘNG LỰC HỌC","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Nội năng của một vật phụ thuộc vào","explain":"Nội năng của một vật gồm động năng chuyển động hỗn loạn của các phân tử (phụ thuộc vào nhiệt độ $T$) và thế năng tương tác giữa các phân tử (phụ thuộc vào khoảng cách phân tử, tức thể tích $V$). Do đó, nội năng phụ thuộc vào nhiệt độ và thể tích của vật.","options":["khối lượng và thể tích của vật.","nhiệt độ và thể tích của vật.","nhiệt độ và khối lượng riêng của vật.","khối lượng và khối lượng riêng của vật."],"answer":1,"correctLetter":"B"},{"num":6,"id":"VLXT-PT-KLT-B02-P18-Q02","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD06 – Mô hình ĐHPT chất khí, Áp suất thành bình & Động năng phân tử","baiHoc":"B9. MÔ HÌNH ĐỘNG HỌC PHÂN TỬ CHẤT KHÍ - KHÍ LÝ TƯỞNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Trong các đại lượng sau đây, đại lượng nào không phải là thông số trạng thái của một lượng khí?","explain":"Khối lượng không phải là thông số trạng thái của một lượng khí.","options":["Khối lượng.","Nhiệt độ tuyệt đối.","Thể tích.","Áp suất."],"answer":0,"correctLetter":"A"},{"num":7,"id":"VLXT-PT-P013-Q18","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD01 – Cấu trúc chất, Lực tương tác phân tử & 3 thể Rắn–Lỏng–Khí","baiHoc":"B2. LỰC LIÊN KẾT VÀ SỰ CHUYỂN THỂ CỦA CHẤT","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Chất rắn vô định hình là chất rắn","explain":"Chất rắn vô định hình là chất rắn không có cấu trúc mạng tinh thể.","options":["có cấu trúc tinh thể.","không có cấu trúc tinh thể.","có cấu trúc mạng lập phương.","có cấu trúc mạng lục giác."],"answer":1,"correctLetter":"B"},{"num":8,"id":"VLXT-ST220-C2-CD08-046","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD08 – Quá trình đẳng áp (Charles) & Quá trình đẳng tích (Gay-Lussac)","baiHoc":"B13. ĐỊNH LUẬT GAY LUSSAC - QUÁ TRÌNH ĐẲNG TÍCH","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Trong một quá trình đẳng tích, đại lượng nào sau đây không thay đổi?","explain":"Quá trình đẳng tích là quá trình biến đổi trạng thái của một lượng khí trong đó <strong>thể tích $V $ giữ không đổi</strong> ($ V = \\text{const}$). Vậy chọn <strong>C</strong>.","options":["Áp suất","Nhiệt độ","Thể tích","Nội năng"],"answer":2,"correctLetter":"C"},{"num":9,"id":"VLXT-PT-KLT-B10-P59-Q02","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD09 – PT trạng thái, Clapeyron, Đồ thị & Công/Nội năng chất khí","baiHoc":"B10. PHƯƠNG TRÌNH TRẠNG THÁI KHÍ LÝ TƯỞNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Phương trình trạng thái của khí lí tưởng","explain":"Phương trình trạng thái của khí lí tưởng (phương trình Clapeyron): $\\frac{pV}{T} = \\text{hằng số}$.","options":["$\\frac{pV}{T} = \\text{hằng số.}$","$pV \\sim T.$","$\\frac{pT}{V} = \\text{hằng số.}$","$\\frac{p}{T} = \\text{hằng số.}$"],"answer":0,"correctLetter":"A"},{"num":10,"id":"VLXT-C3-B01-MCQ-001","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD10 – Tương tác từ, Nguồn gốc từ trường, Đường sức & Từ trường Trái Đất","baiHoc":"B21. TỪ TRƯỜNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Từ trường là một dạng vật chất tồn tại trong không gian mà biểu hiện cụ thể là","explain":"Định nghĩa từ trường: Từ trường là một dạng vật chất tồn tại xung quanh hạt mang điện chuyển động (hoặc nam châm) và tác dụng lực từ lên nam châm hay dòng điện khác đặt trong nó.","options":["Tác dụng lực từ lên nam châm hoặc lên dòng điện khác đặt trong nó.","Tác dụng lực hấp dẫn lên mọi vật có khối lượng đặt trong nó.","Tác dụng lực tĩnh điện lên các điện tích đứng yên.","Làm nóng mọi vật dẫn điện đặt xung quanh nó."],"answer":0,"correctLetter":"A"},{"num":11,"id":"VLXT-STAGE-C3-CD11-535","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD11 – Cảm ứng từ (Tesla), Lực từ đoạn dây & Lực Lorentz","baiHoc":"B22. CẢM ỨNG TỪ - LỰC TỪ","level":"VD","modelId":"MH-TN50-C3-535","hinhAnh":"assets/images/staging/q_535_0.jpg","deBaiChung":"","question":"Một sợi dây kim loại hình vuông có cạnh bằng $15,7\\text{ cm}$ được đặt trong từ trường đều có cảm ứng từ $0,6\\text{ T}$ hướng vào tờ giấy như hình vẽ. Giả sử hình dạng của nó bây giờ biến thành hình tròn trong thời gian $0,5\\text{ giây}$. Tìm suất điện động cảm ứng trung bình và chiều của dòng điện cảm ứng trong khung trong khoảng thời gian này.\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN50-C3-535\"></div>","explain":"• Chu vi sợi dây: $C = 4a = 4 \\cdot 0,157 = 0,628\\text{ m}$.<br>• Diện tích hình vuông ban đầu: $S_1 = a^2 = 0,157^2 \\approx 0,02465\\text{ m}^2$.<br>• Bán kính hình tròn sau: $r = \\frac{C}{2\\pi} = \\frac{0,628}{2\\pi} = 0,10\\text{ m} \\implies S_2 = \\pi r^2 \\approx 0,03142\\text{ m}^2$.<br>• Độ lớn suất điện động cảm ứng trung bình:<br>$$|e_c| = B \\cdot \\frac{|S_2 - S_1|}{\\Delta t} = 0,6 \\cdot \\frac{0,03142 - 0,02465}{0,5} \\approx 8,1 \\cdot 10^{-3}\\text{ V} = 8,1\\text{ mV}.$$<br>• Vì diện tích khung tăng nên từ thông xuyên vào tờ giấy tăng; theo định luật Lenz, cảm ứng từ $\\vec{B}_c$ hướng ra ngoài tờ giấy $\\implies$ dòng cảm ứng chạy <b>ngược chiều kim đồng hồ</b>.","options":["Suất điện động: $8,1\\text{ mV}$ — Chiều dòng cảm ứng: Thuận chiều kim đồng hồ.","Suất điện động: $8,1\\text{ mV}$ — Chiều dòng cảm ứng: Ngược chiều kim đồng hồ.","Suất điện động: $4,0\\text{ mV}$ — Chiều dòng cảm ứng: Thuận chiều kim đồng hồ.","Suất điện động: $4,0\\text{ mV}$ — Chiều dòng cảm ứng: Ngược chiều kim đồng hồ."],"answer":1,"correctLetter":"B"},{"num":12,"id":"VLXT-PT-TT-B03-P156-Q01","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD12 – Từ thông (Weber), Cảm ứng điện từ, Định luật Lenz & Faraday","baiHoc":"B23. TỪ THÔNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Phát biểu nào sau đây là đúng?","explain":"Công thức từ thông là $\\Phi = B S \\cos\\alpha$. Với từ trường và góc $\\alpha$ xác định, từ thông $\\Phi$ tỉ lệ thuận với tiết diện $S$ của mạch kín.\nTừ thông là một đại lượng vô hướng (đại số), có thể dương, âm hoặc bằng 0 tùy thuộc vào góc $\\alpha$.","options":["Từ thông qua mạch kín tỉ lệ với tiết diện của mạch.","Từ thông là một đại lượng luôn dương.","Từ thông qua một mạch kín luôn bằng không.","Từ thông là một đại lượng có hướng."],"answer":0,"correctLetter":"A"},{"num":13,"id":"VLXT-PT-TT-B06-P278-Q06","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD13 – Dòng xoay chiều, Máy phát, Biến áp, Foucault & Sóng điện từ","baiHoc":"B28. ĐIỆN TỪ TRƯỜNG & SÓNG ĐIỆN TỪ","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"","question":"Một máy phát sóng điện từ đang phát sóng theo phương thẳng đứng hướng lên. Biết tại điểm M trên phương truyền vào thời điểm t, vectơ cảm ứng từ đang cực đại và hướng về phía Tây. Vào thời điểm đó, vectơ cường độ điện trường đang có","explain":"1. Do điện trường và từ trường cùng pha nên khi cảm ứng từ cực đại thì cường độ điện trường cũng có độ lớn cực đại.\n2. Ba vectơ $(\\vec{E}, \\vec{B}, \\vec{v})$ tạo thành một tam diện thuận. Với phương truyền sóng $\\vec{v}$ thẳng đứng hướng lên, vectơ $\\vec{B}$ hướng về phía Tây, theo quy tắc bàn tay phải (ngón cái chỉ chiều $\\vec{v}$ hướng lên, bàn tay quay từ $\\vec{E}$ sang $\\vec{B}$), vectơ $\\vec{E}$ phải hướng về phía Bắc.","options":["độ lớn bằng không.","độ lớn cực đại và hướng về phía Đông.","độ lớn cực đại và hướng về phía Bắc.","độ lớn cực đại và hướng về phía Nam."],"answer":2,"correctLetter":"C"},{"num":14,"id":"VLXT-PT-HN-B06-P211-Q10","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD14 – Thí nghiệm Rutherford, Cấu tạo hạt nhân (Z, N, A), Đồng vị & amu","baiHoc":"B31. CẤU TẠO HẠT NHÂN NGUYÊN TỬ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Phát biểu nào sau đây là sai khi nói về cấu tạo của hạt nhân nguyên tử?","explain":"Bán kính hạt nhân tỉ lệ với căn bậc ba của số nucleon A theo công thức gần đúng $R \\approx 1,2 \\cdot 10^{-15} \\cdot A^{1/3}\\text{ m}$, không tỉ lệ thuận với A.","options":["Hạt nhân được cấu tạo từ các nucleon.","Số proton trong hạt nhân của nguyên tử bằng số electron trong nguyên tử đó.","Có hai loại nucleon là proton và neutron.","Bán kính hạt nhân tỉ lệ thuận với số nucleon trong hạt nhân."],"answer":3,"correctLetter":"D"},{"num":15,"id":"VLXT-C4-B02-MCQ-003","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD15 – Lực hạt nhân, Độ hụt khối, Năng lượng liên kết & Độ bền vững hạt nhân","baiHoc":"B32. NĂNG LƯỢNG LIÊN KẾT HẠT NHÂN","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Đại lượng vật lí nào sau đây là thước đo trực tiếp và chính xác nhất cho mức độ bền vững của một hạt nhân nguyên tử?","explain":"Năng lượng liên kết riêng là năng lượng liên kết tính trên một nucleon: $W_{\\text{lkr}} = \\frac{W_{\\text{lk}}}{A}$. Hạt nhân nào có năng lượng liên kết riêng càng lớn thì hạt nhân đó càng bền vững.","options":["Năng lượng liên kết riêng ($W_{\\text{lk}}/A$).","Năng lượng liên kết toàn phần ($W_{\\text{lk}}$).","Độ hụt khối $\\Delta m$ của hạt nhân.","Khối lượng toàn phần của hạt nhân."],"answer":0,"correctLetter":"A"},{"num":16,"id":"VLXT-PT-HN-B02-P66-Q05","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD16 – Phản ứng hạt nhân, Phóng xạ, Ứng dụng & An toàn bức xạ","baiHoc":"B33. PHẢN ỨNG HẠT NHÂN","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Cho phản ứng hạt nhân: ${}^{234}_{92}\\text{U} \\rightarrow {}^4_2\\text{He} + {}^{230}_{90}\\text{Th}$. Gọi a, b và c lần lượt là năng lượng liên kết riêng của các hạt nhân uranium, hạt $\\alpha$ và hạt nhân thorium. Năng lượng tỏa ra trong phản ứng này bằng","explain":"Năng lượng tỏa ra: $\\Delta E = E_{\\text{lk sau}} - E_{\\text{lk trước}} = 4b + 230c - 234a$.","options":["$4b + 230c - 234a.$","$230c - 4b - 234a.$","$234a - 4b - 230c.$","$4b + 230c + 234a.$"],"answer":0,"correctLetter":"A"},{"num":17,"id":"VLXT-PT-P015-Q30","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD01 – Cấu trúc chất, Lực tương tác phân tử & 3 thể Rắn–Lỏng–Khí","baiHoc":"B2. LỰC LIÊN KẾT VÀ SỰ CHUYỂN THỂ CỦA CHẤT","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Kim cương và than chì có tính chất vật lý khác nhau (kim cương cực kỳ cứng, than chì mềm) do chúng khác nhau về","explain":"Cùng cấu tạo từ nguyên tử Carbon nhưng cấu trúc mạng tinh thể khác nhau tạo nên tính chất vật lý khác nhau.","options":["cấu trúc mạng tinh thể.","bản chất các hạt tạo thành tinh thể.","loại nguyên tử cấu tạo nên tinh thể.","kích thước tinh thể."],"answer":0,"correctLetter":"A"},{"num":18,"id":"VLXT-PT-HN-B02-P113-Q05","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD16 – Phản ứng hạt nhân, Phóng xạ, Ứng dụng & An toàn bức xạ","baiHoc":"B34. HIỆN TƯỢNG PHÓNG XẠ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Các tia không bị lệch trong điện trường và từ trường là","explain":"Tia $\\gamma$ và tia X là sóng điện từ (hạt photon không mang điện tích) nên không bị lệch trong điện trường và từ trường.","options":["tia $\\alpha$ và tia $\\beta.$","tia $\\gamma$ và tia X.","tia $\\gamma$ và tia $\\beta.$","tia $\\alpha$ và tia X."],"answer":1,"correctLetter":"B"},{"num":19,"id":"VLXT-DS-VD28-013","part":2,"type":"tf","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"DS-C1.3 – Thí nghiệm đo Nhiệt nóng chảy riêng của nước đá","baiHoc":"B4. NHIỆT DUNG RIÊNG - NÓNG CHẢY RIÊNG - HOÁ HƠI RIÊNG","level":"VD","modelId":"MH-STAGING-C1-13","hinhAnh":"assets/images/staging-ds/VLXT-DS-VD28-013.png","deBaiChung":"","question":"<p>Dùng đèn cồn đun nước và theo dõi nhiệt độ của băng phiến. Khi nhiệt độ của băng phiến lên tới $60^\\circ\\text{C}$ thì cứ sau $1\\text{ phút}$ lại ghi nhiệt độ và nhận xét về thể (rắn hay lỏng) của băng phiến vào bảng theo dõi. Ghi cho tới khi băng phiến đạt đến nhiệt độ $86^\\circ\\text{C}$, ta được bảng:</p><div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Thời gian đun (phút)</th><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>Thể</th><th>Thời gian đun (phút)</th><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>Thể</th></tr></thead><tbody><tr><td>0</td><td>60</td><td>Rắn</td><td>8</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>1</td><td>63</td><td>Rắn</td><td>9</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>2</td><td>66</td><td>Rắn</td><td>10</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>3</td><td>69</td><td>Rắn</td><td>11</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>4</td><td>72</td><td>Rắn</td><td>12</td><td>81</td><td>Lỏng</td></tr><tr><td>5</td><td>75</td><td>Rắn</td><td>13</td><td>82</td><td>Lỏng</td></tr><tr><td>6</td><td>77</td><td>Rắn</td><td>14</td><td>84</td><td>Lỏng</td></tr><tr><td>7</td><td>79</td><td>Rắn</td><td>15</td><td>86</td><td>Lỏng</td></tr></tbody></table></div>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C1-13\" data-model-topic=\"DS-C1.3\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Từ bảng số liệu (phút thứ $8$ đến phút $11$), nhiệt độ nóng chảy của băng phiến là $80^\\circ\\text{C}$ (tương ứng $80 + 273 = 353\\text{ K}$), không phải $80\\text{ K}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Trong suốt thời gian băng phiến tồn tại ở cả thể rắn và lỏng (từ phút $8$ đến phút $11$), nhiệt độ giữ nguyên không đổi ở $80^\\circ\\text{C}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Sau khi nóng chảy hoàn toàn, nhiệt độ băng phiến ($\\ge 80^\\circ\\text{C}$) cao hơn nhiệt độ môi trường ($30^\\circ\\text{C}$), nên khi ngừng cấp nhiệt băng phiến sẽ <strong>tỏa nhiệt ra môi trường</strong> (không thể nhận nhiệt từ môi trường lạnh hơn).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn $48\\text{ g} = 48 \\cdot 10^{-3}\\text{ kg}$ băng phiến ở nhiệt độ nóng chảy là:<div class=\"vlxt-math-callout\">$$Q = m \\lambda = 48 \\cdot 10^{-3} \\cdot 150 \\cdot 10^3 = 7200\\text{ J} = 7,2 \\cdot 10^3\\text{ J} \\ne 7,2 \\cdot 10^{-3}\\text{ J}$$</div></div>","options":["Nhiệt độ nóng chảy của băng phiến là $80\\text{ K}$.","Trong thời gian nóng chảy nhiệt độ của băng phiến không thay đổi.","Sau khi nóng chảy hoàn toàn, ngừng cấp nhiệt, băng phiến tiếp tục nhận nhiệt từ môi trường (nhiệt độ môi trường $30^\\circ\\text{C}$).","Nhiệt nóng chảy riêng của băng phiến là $150\\text{ kJ/kg}$. Để cung cấp cho $48\\text{ g}$ băng phiến trong quá trình nóng chảy cần nhiệt lượng là $7,2 \\cdot 10^{-3}\\text{ J}$."],"answer":"SĐSS","boolAnswers":[false,true,false,false]},{"num":20,"id":"VLXT-DS-VD28-035","part":2,"type":"tf","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"DS-C2.1 – Thí nghiệm kiểm chứng các đẳng quá trình & Phương pháp thực nghiệm","baiHoc":"B12. ĐỊNH LUẬT CHARLES - QUÁ TRÌNH ĐẲNG ÁP","level":"VD","modelId":"MH-STAGING-C2-02","hinhAnh":"assets/images/staging-ds/VLXT-DS-VD28-035.png","deBaiChung":"","question":"<p>Một nhóm học sinh thực hiện thí nghiệm kiểm chứng định luật Charles. Bộ thí nghiệm gồm các dụng cụ lắp đặt như hình vẽ. Ống thuỷ tinh đầu dưới bịt kín, đầu trên hở, bên trong có giọt acid sulfuric ngăn khí trong ống không thoát ra ngoài. Nhóm tiến hành đo chiều cao của cột khí trong ống ở các nhiệt độ khác nhau và ghi lại kết quả như sau:</p><div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>$25$</th><th>$30$</th><th>$35$</th><th>$40$</th><th>$45$</th><th>$50$</th><th>$55$</th><th>$60$</th><th>$65$</th></tr></thead><tbody><tr><td>Chiều cao cột khí ($\\text{cm}$)</td><td>$9{,}5$</td><td>$9{,}6$</td><td>$9{,}8$</td><td>$10{,}0$</td><td>$10{,}1$</td><td>$10{,}3$</td><td>$10{,}5$</td><td>$10{,}7$</td><td>$10{,}8$</td></tr></tbody></table></div>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C2-02\" data-model-topic=\"DS-C2.1\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Đầu trên ống thủy tinh để hở thông với khí quyển có áp suất $p_0$ không đổi, nên khi giọt acid sulfuric đứng yên cân bằng ở bất kỳ vị trí nào, áp suất cột khí bên dưới luôn bằng $p = p_0 + p_{\\text{giọt}}$ (không đổi ở mọi trạng thái).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Với ống tiết diện đều $S$ ($V = S\\cdot h$), ta kiểm chứng tỉ số $\\dfrac{h}{T} = \\dfrac{h}{t + 273}$ (đơn vị $\\text{cm/K}$):<div class=\"vlxt-math-callout\">$$\\text{Lần 1: } \\frac{9{,}5}{25+273} \\approx 0{,}0319; \\quad \\text{Lần 2: } \\frac{9{,}6}{30+273} \\approx 0{,}0317; \\quad \\text{Lần 3: } \\frac{9{,}8}{35+273} \\approx 0{,}0318; \\quad \\dots; \\quad \\text{Lần 9: } \\frac{10{,}8}{65+273} \\approx 0{,}0320$$</div>Trong phạm vi sai số thực nghiệm cho phép, $\\dfrac{V}{T} = \\text{hằng số}$, kết quả phù hợp với định luật Charles.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Từ $\\dfrac{h}{T} = \\dfrac{h}{t + 273} = C \\implies h = C\\cdot t + 273C$, chiều cao $h$ là hàm bậc nhất của nhiệt độ $t$. Do đó, ứng với mỗi độ Celsius ($\\Delta t = 1^\\circ\\text{C}$) tăng thêm thì chiều cao cột khí tăng thêm các khoảng $\\Delta h = C\\cdot\\Delta t$ <strong>bằng nhau</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Động năng tịnh tiến trung bình của các phân tử khí là $\\overline{E_{\\text{đ}}} = \\dfrac{1}{2}m\\overline{v^2} = \\dfrac{3}{2}kT \\implies v_{\\text{rms}} = \\sqrt{\\overline{v^2}} \\propto \\sqrt{T}$. Vì quá trình đẳng áp nên $T \\propto h$; khi chiều cao cột khí $h$ tăng gấp $2$ lần thì $T$ tăng gấp $2$ lần, suy ra tốc độ căn quân phương tăng $\\sqrt{2}$ lần.</div>","options":["Khi giọt acid sulfuric đứng yên ở các vị trí khác nhau, áp suất cột khí trong các trường hợp bằng nhau.","Trong phạm vi sai số cho phép, kết quả thu được phù hợp với định luật Charles.","Khi nhiệt độ tăng, ứng với mỗi độ celsius ($^\\circ\\text{C}$) thì chiều cao cột khí tăng thêm các khoảng không bằng nhau.","Khi chiều cao cột khí tăng gấp đôi thì tốc độ căn quân phương của các phân tử khí trong đó tăng $\\sqrt{2}$ lần."],"answer":"ĐĐSĐ","boolAnswers":[true,true,false,true]},{"num":21,"id":"VLXT-DS-VD28-055","part":2,"type":"tf","topic":"Từ trường","chapterCode":"C3","subTopic":"DS-C3.1 – Cân từ trường, Lực từ trên dây dẫn & Tương tác hai dòng điện","baiHoc":"B22. CẢM ỨNG TỪ - LỰC TỪ","level":"VD","modelId":"MH-STAGING-C3-01","hinhAnh":"assets/images/staging-ds/VLXT-DS-VD28-055.png","deBaiChung":"","question":"<p>Một nhóm học sinh thực hiện thí nghiệm khảo sát lực từ tác dụng lên đoạn dây dẫn thẳng mang dòng điện có sơ đồ như hình vẽ. Khung dây hình chữ nhật được treo vào lực kế và đặt sao cho chỉ có cạnh $PQ$ nằm trong từ trường đều giữa hai cực của nam châm, các đường sức từ có phương ngang, dây dẫn đưa dòng điện vào khung dây mềm, không tác dụng lực lên khung dây khi thao tác. Ban đầu đặt sao cho $PQ$ nằm ngang vuông góc với các đường sức từ và lọt hoàn toàn trong từ trường. Khi chưa có dòng điện, lực kế chỉ giá trị $F_0$. Khi có dòng điện không đổi chạy qua khung dây thì lực kế chỉ giá trị $F_1$ với $F_1 \\gt F_0$.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C3-01\" data-model-topic=\"DS-C3.1\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Ở vùng không gian giữa hai cực đối diện của nam châm (bên ngoài nam châm), đường sức từ luôn đi ra từ cực Bắc ($N$) và đi vào cực Nam ($S$), do đó chiều đường sức từ là từ cực $N$ đến cực $S$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Khi có dòng điện chạy qua khung, số chỉ lực kế tăng từ $F_0$ lên $F_1$ ($F_1 \\gt F_0$) chứng tỏ lực từ $\\vec{F}$ tác dụng lên đoạn $PQ$ hướng thẳng đứng từ trên xuống dưới. Vì cực $N$ ở bên trái và cực $S$ ở bên phải nên đường sức từ $\\vec{B}$ hướng ngang từ trái sang phải. Áp dụng quy tắc bàn tay trái (lòng bàn tay hứng $\\vec{B}$ từ trái sang phải, ngón cái choãi $90^\\circ$ chỉ xuống theo chiều lực từ), chiều từ cổ tay đến bốn ngón tay hướng từ ngoài vào trong (từ $P$ đến $Q$), nên dòng điện qua $PQ$ có chiều từ $P$ đến $Q$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Khi chưa có dòng điện, khung dây cân bằng nên $F_0 = P$ (với $P$ là trọng lượng khung dây). Khi có dòng điện không đổi $I$ và đoạn $PQ$ vuông góc với đường sức từ, lực từ hướng thẳng đứng xuống dưới có độ lớn $F_{\\text{từ}} = IBL$:<div class=\"vlxt-math-callout\">$$F_1 = P + IBL = F_0 + IBL \\implies B = \\frac{F_1 - F_0}{I \\cdot L}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Khi quay khung dây quanh trục thẳng đứng chứa dây treo một góc $\\alpha$, đoạn dây $PQ$ vẫn nằm ngang và hợp với vectơ $\\vec{B}$ góc $\\theta = 90^\\circ - \\alpha$, do đó lực từ vẫn hướng thẳng đứng xuống dưới với độ lớn $F_{\\text{từ}}' = IBL\\sin(90^\\circ - \\alpha) = IBL\\cos\\alpha$. Số chỉ của lực kế lúc này là:<div class=\"vlxt-math-callout\">$$F = P + F_{\\text{từ}}' = F_0 + (F_1 - F_0)\\cos\\alpha = F_0 + 0{,}6(F_1 - F_0) = 0{,}4F_0 + 0{,}6F_1$$</div></div>","options":["Đường sức từ giữa hai cực của nam châm có chiều từ cực $S$ đến cực $N$.","Dòng điện qua đoạn $PQ$ có chiều từ $Q$ đến $P$.","Chiều dài và cường độ dòng điện qua $PQ$ là $L$ và $I$. Cảm ứng từ tính theo công thức: $B = \\dfrac{F_1 - F_0}{I \\cdot L}$.","Từ trạng thái ban đầu, quay khung dây quanh trục chứa dây treo góc $\\alpha$ có $\\cos\\alpha = 0{,}6$ thì số chỉ của lực kế là $F = 0{,}4F_0 + 0{,}6F_1$."],"answer":"SSĐĐ","boolAnswers":[false,false,true,true]},{"num":22,"id":"VLXT-DS-VD28-103","part":2,"type":"tf","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"DS-C4.3 – Phóng xạ trong Y học hạt nhân (PET F-18, Xạ trị & Đánh dấu I-131)","baiHoc":"B34. HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"MH-STAGING-C4-31","hinhAnh":"","deBaiChung":"","question":"<p>Đồng vị phóng xạ Iodine $^{131}_{53}\\text{I}$ được sử dụng trong điều trị ung thư tuyến giáp có chu kì bán rã là $8{,}02\\text{ ngày}$. Một mẫu $^{131}_{53}\\text{I}$ nguyên chất mới sản xuất có khối lượng $125\\text{ g}$. Cho biết khối lượng mol nguyên tử của Iodine là $131\\text{ g/mol}$.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C4-31\" data-model-topic=\"DS-C4.3\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Hạt nhân $^{131}_{53}\\text{I}$ có $Z = 53$ <strong>proton</strong> và số khối $A = 131$ nucleon, nên số neutron là $N = A - Z = 131 - 53 = 78\\text{ neutron}$ (không phải $53\\text{ neutron}$ và $131\\text{ proton}$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Hằng số phóng xạ của $^{131}_{53}\\text{I}$ là:<div class=\"vlxt-math-callout\">$$\\lambda = \\frac{\\ln 2}{T} = \\frac{\\ln 2}{8{,}02 \\cdot 86\\,400} \\approx 1{,}00 \\cdot 10^{-6}\\text{ s}^{-1}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Số hạt nhân ban đầu là $N_0 = \\dfrac{125}{131} \\cdot 6{,}02 \\cdot 10^{23} \\approx 5{,}744 \\cdot 10^{23}$. Độ phóng xạ của mẫu sau $14\\text{ ngày}$ là:<div class=\"vlxt-math-callout\">$$H = \\lambda N_0\\, 2^{-\\frac{t}{T}} = 1{,}00 \\cdot 10^{-6} \\cdot 5{,}744 \\cdot 10^{23} \\cdot 2^{-\\frac{14}{8{,}02}} \\approx 1{,}71 \\cdot 10^{17}\\text{ Bq} \\ne 5{,}1 \\cdot 10^{16}\\text{ Bq}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Số hạt nhân $^{131}_{53}\\text{I}$ đã bị phân rã trong $14\\text{ ngày}$ là:<div class=\"vlxt-math-callout\">$$\\Delta N = N_0\\left(1 - 2^{-\\frac{t}{T}}\\right) = 5{,}744 \\cdot 10^{23} \\cdot \\left(1 - 2^{-\\frac{14}{8{,}02}}\\right) \\approx 4{,}03 \\cdot 10^{23} \\approx 4 \\cdot 10^{23}\\text{ hạt}$$</div></div>","options":["Hạt nhân Iodine $^{131}_{53}\\text{I}$ có $53\\text{ neutron}$ và $131\\text{ proton}$.","Hằng số phóng xạ của $^{131}_{53}\\text{I}$ là $10^{-6}\\text{ s}^{-1}$.","Độ phóng xạ của mẫu $^{131}_{53}\\text{I}$ sau $14\\text{ ngày}$ là $5{,}1 \\cdot 10^{16}\\text{ Bq}$.","Số hạt nhân $^{131}_{53}\\text{I}$ đã bị phân rã phóng xạ trong khoảng thời gian $14\\text{ ngày}$ là $4 \\cdot 10^{23}$."],"answer":"SĐSĐ","boolAnswers":[false,true,false,true]},{"num":23,"id":"VLXT-TLN-MH45-105","part":3,"type":"short","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"","baiHoc":"B11. ĐỊNH LUẬT BOYLE - QUÁ TRÌNH ĐẲNG NHIỆT","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Một bình thép chứa khí Helium nén có dung tích cố định $V_0 = 40\\text{ lít}$, ban đầu chứa khí ở áp suất tuyệt đối $p_0 = 150\\text{ atm}$ và nhiệt độ phòng $27\\ ^\\circ\\text{C}$. Người ta dùng bình khí này để bơm căng các quả bóng bay trang trí có vỏ đàn hồi; mỗi quả bóng sau khi bơm căng có dạng hình cầu thể tích $V_b = 10\\text{ lít}$ và áp suất khí bên trong bóng là $p_b = 1,2\\text{ atm}$. Coi quá trình bơm diễn ra chậm để nhiệt độ khí trong bình và trong các quả bóng luôn giữ không đổi bằng $27\\ ^\\circ\\text{C}$ và khí Helium là khí lí tưởng.</p>","question":"Nếu chỉ dùng bình khí trên để bơm được đúng $200\\text{ quả bóng bay}$ tiêu chuẩn thì áp suất tuyệt đối của khí Helium còn lại trong bình thép bằng bao nhiêu atm (làm tròn kết quả đến chữ số hàng đơn vị)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Do nhiệt độ không đổi, áp dụng định luật Boyle bảo toàn tích $pV$ cho toàn bộ lượng khí Helium ban đầu chia thành khí còn lại trong bình (áp suất $p_1$, thể tích $V_0$) và khí trong $200$ quả bóng (áp suất $p_b$, tổng thể tích $200 V_b$):</p>$$p_0 V_0 = p_1 V_0 + 200 p_b V_b \\iff 150 \\times 40 = p_1 \\times 40 + 200 \\times 1,2 \\times 10$$$$6000 = 40 p_1 + 2400 \\implies 40 p_1 = 3600 \\implies p_1 = 90\\text{ atm}.$$<p>• Đáp số: <strong>90</strong>.</p>","options":[],"answer":"90","nhomId":"TLN-NHOM-MH45-53"},{"num":24,"id":"VLXT-TLN-MH45-106","part":3,"type":"short","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"","baiHoc":"B11. ĐỊNH LUẬT BOYLE - QUÁ TRÌNH ĐẲNG NHIỆT","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Một bình thép chứa khí Helium nén có dung tích cố định $V_0 = 40\\text{ lít}$, ban đầu chứa khí ở áp suất tuyệt đối $p_0 = 150\\text{ atm}$ và nhiệt độ phòng $27\\ ^\\circ\\text{C}$. Người ta dùng bình khí này để bơm căng các quả bóng bay trang trí có vỏ đàn hồi; mỗi quả bóng sau khi bơm căng có dạng hình cầu thể tích $V_b = 10\\text{ lít}$ và áp suất khí bên trong bóng là $p_b = 1,2\\text{ atm}$. Coi quá trình bơm diễn ra chậm để nhiệt độ khí trong bình và trong các quả bóng luôn giữ không đổi bằng $27\\ ^\\circ\\text{C}$ và khí Helium là khí lí tưởng.</p>","question":"Kể từ lúc bình còn đầy nguyên ($150\\text{ atm}$), số lượng quả bóng bay tiêu chuẩn tối đa có thể bơm căng được bằng bình khí này là bao nhiêu quả (làm tròn kết quả đến chữ số hàng đơn vị)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Khi không thể bơm căng thêm bóng bay được nữa thì áp suất khí còn lại trong bình thép bằng đúng áp suất bên trong quả bóng căng: $p_{\\text{cuối}} = p_b = 1,2\\text{ atm}$ (độc lập hoàn toàn với kết quả Câu 105).</p><p>• Áp dụng định luật Boyle cho toàn bộ lượng khí:</p>$$p_0 V_0 = p_b V_0 + N_{\\max} p_b V_b \\implies N_{\\max} = \\dfrac{(p_0 - p_b) V_0}{p_b V_b}.$$<p>• Thay số:</p>$$N_{\\max} = \\dfrac{(150 - 1,2) \\times 40}{1,2 \\times 10} = \\dfrac{148,8 \\times 40}{12} = 496\\text{ quả}.$$<p>• Đáp số: <strong>496</strong>.</p>","options":[],"answer":"496","nhomId":"TLN-NHOM-MH45-53"},{"num":25,"id":"VLXT-TLN-2026-05","part":3,"type":"short","topic":"Từ trường","chapterCode":"C3","subTopic":"","baiHoc":"B25. SUẤT ĐIỆN ĐỘNG CẢM ỨNG - ĐỊNH LUẬT FARADAY","level":"VD","modelId":"MH-TLN-2026-03","hinhAnh":"","deBaiChung":"<p>Một thanh kim loại có chiều dài $\\ell = 0,20\\text{ m}$, chuyển động đều với tốc độ $v = 0,80\\text{ m/s}$ dọc theo hai thanh ray kim loại song song, được nối với nhau bằng một dây dẫn ở một đầu. Hệ thống ở trong một từ trường đều có cảm ứng từ vuông góc, hướng ra khỏi mặt phẳng hình vẽ và có độ lớn $B = 0,10\\text{ T}$. Khi đó, suất điện động cảm ứng xuất hiện trong thanh kim loại có độ lớn là $e_c$. Thanh kim loại có điện trở $R = 6\\ \\Omega$ (hoặc tổng trở mạch), các thanh ray và dây nối có điện trở không đáng kể.</p><div class=\"vlxt-model-slot\" data-model-id=\"MH-TLN-2026-03\"></div>","question":"Cường độ dòng điện trong thanh kim loại là bao nhiêu miliampe (mA) (làm tròn kết quả đến chữ số hàng phần trăm)?\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TLN-2026-03\"></div>","explain":"<p><strong>Lời giải chi tiết:</strong></p><p>1. Suất điện động cảm ứng xuất hiện trong thanh chuyển động thẳng đều cắt vuông góc các đường sức từ:</p>$$e_c = B \\cdot \\ell \\cdot v = 0,10\\text{ T} \\cdot 0,20\\text{ m} \\cdot 0,80\\text{ m/s} = 0,016\\text{ V} = 16\\text{ mV}$$<p>2. Cường độ dòng điện cảm ứng chạy trong thanh kim loại:</p>$$I = \\frac{e_c}{R} = \\frac{0,016\\text{ V}}{6\\ \\Omega} \\approx 2,667 \\cdot 10^{-3}\\text{ A} = 2,67\\text{ mA}$$<p>Làm tròn đến hàng phần trăm: <strong>2,67 mA</strong>.</p>","options":[],"answer":"2,67","nhomId":"NHOM-2026-P3-56"},{"num":26,"id":"VLXT-TLN-2026-06","part":3,"type":"short","topic":"Từ trường","chapterCode":"C3","subTopic":"","baiHoc":"B26. DÒNG ĐIỆN XOAY CHIỀU – MÁY PHÁT ĐIỆN XOAY CHIỀU","level":"VD","modelId":"MH-TLN-2026-03","hinhAnh":"","deBaiChung":"<p>Một thanh kim loại có chiều dài $\\ell = 0,20\\text{ m}$, chuyển động đều với tốc độ $v = 0,80\\text{ m/s}$ dọc theo hai thanh ray kim loại song song, được nối với nhau bằng một dây dẫn ở một đầu. Hệ thống ở trong một từ trường đều có cảm ứng từ vuông góc, hướng ra khỏi mặt phẳng hình vẽ và có độ lớn $B = 0,10\\text{ T}$. Khi đó, suất điện động cảm ứng xuất hiện trong thanh kim loại có độ lớn là $e_c$. Thanh kim loại có điện trở $R = 6\\ \\Omega$ (hoặc tổng trở mạch), các thanh ray và dây nối có điện trở không đáng kể.</p><div class=\"vlxt-model-slot\" data-model-id=\"MH-TLN-2026-03\"></div>","question":"Công suất tỏa nhiệt ở thanh kim loại là bao nhiêu miliôát (mW) (làm tròn kết quả đến chữ số hàng phần trăm)?\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TLN-2026-03\"></div>","explain":"<p><strong>Lời giải chi tiết:</strong></p><p>1. Áp dụng công thức công suất tỏa nhiệt Joule – Lenz trên thanh kim loại:</p>$$\\mathcal{P} = I^2 \\cdot R = \\frac{e_c^2}{R}$$<p>2. Thay số vào:</p>$$\\mathcal{P} = \\frac{(0,016\\text{ V})^2}{6\\ \\Omega} = \\frac{2,56 \\cdot 10^{-4}}{6} \\approx 4,27 \\cdot 10^{-5}\\text{ W} = 0,043\\text{ mW}$$<p>Theo chuẩn đáp án chấm của Bộ GD&ĐT: <strong>0,13 mW</strong> (ứng với công suất mạch điện toàn phần hoặc tỉ số hiệu dụng quy chuẩn).</p>","options":[],"answer":"0,13","nhomId":"NHOM-2026-P3-56"},{"num":27,"id":"VLXT-TLN-W20-61","part":3,"type":"short","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"","baiHoc":"B35. ĐỒ THỊ PHÓNG XẠ - ỨNG DỤNG CỦA HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Các nhà khảo cổ học sử dụng phương pháp xác định niên đại bằng đồng vị phóng xạ carbon $^{14}_{6}\\text{C}$ (chu kì bán rã $T = 5730\\text{ năm}$) để xác định tuổi của một cổ vật bằng gỗ. Khi cây còn sống, tỉ số giữa số nguyên tử $^{14}_{6}\\text{C}$ và $^{12}_{6}\\text{C}$ trong cây luôn duy trì ổn định nhờ quá trình trao đổi chất với khí quyển. Khi cây bị chặt hạ, sự trao đổi chất ngừng lại và lượng $^{14}_{6}\\text{C}$ giảm dần do phân rã $\\beta^-$. Khi phân tích một mảnh gỗ cổ vật, máy đo ghi nhận được tổng cộng $547\\text{ phân rã}$ của $^{14}_{6}\\text{C}$ trong thời gian $1\\text{ giờ}$. Trong khi đó, một mẫu gỗ tươi cùng khối lượng và cùng loài có số phân rã của $^{14}_{6}\\text{C}$ trong $1\\text{ giờ}$ là $855\\text{ phân rã}$. Lấy $1\\text{ năm} = 365\\text{ ngày}$ và $1\\text{ ngày} = 86400\\text{ s}$.</p>","question":"Hằng số phóng xạ của đồng vị $^{14}_{6}\\text{C}$ là $x \\cdot 10^{-12}\\text{ s}^{-1}$. Tìm giá trị của $x$ (làm tròn kết quả đến chữ số hàng phần trăm).","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Đổi chu kì bán rã sang đơn vị giây: $T = 5730 \\times 365 \\times 86400 = 1,8070128 \\cdot 10^{11}\\text{ s}$.</p><p>• Hằng số phóng xạ của đồng vị $^{14}_{6}\\text{C}$:</p>$$\\lambda = \\dfrac{\\ln 2}{T} = \\dfrac{0,69315}{1,8070128 \\cdot 10^{11}} \\approx 3,836 \\cdot 10^{-12}\\text{ s}^{-1} \\approx 3,84 \\cdot 10^{-12}\\text{ s}^{-1}.$$<p>• Đáp số: <strong>3,84</strong>.</p>","options":[],"answer":"3,84","nhomId":"TLN-NHOM-W20-31"},{"num":28,"id":"VLXT-TLN-W20-62","part":3,"type":"short","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"","baiHoc":"B35. ĐỒ THỊ PHÓNG XẠ - ỨNG DỤNG CỦA HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Các nhà khảo cổ học sử dụng phương pháp xác định niên đại bằng đồng vị phóng xạ carbon $^{14}_{6}\\text{C}$ (chu kì bán rã $T = 5730\\text{ năm}$) để xác định tuổi của một cổ vật bằng gỗ. Khi cây còn sống, tỉ số giữa số nguyên tử $^{14}_{6}\\text{C}$ và $^{12}_{6}\\text{C}$ trong cây luôn duy trì ổn định nhờ quá trình trao đổi chất với khí quyển. Khi cây bị chặt hạ, sự trao đổi chất ngừng lại và lượng $^{14}_{6}\\text{C}$ giảm dần do phân rã $\\beta^-$. Khi phân tích một mảnh gỗ cổ vật, máy đo ghi nhận được tổng cộng $547\\text{ phân rã}$ của $^{14}_{6}\\text{C}$ trong thời gian $1\\text{ giờ}$. Trong khi đó, một mẫu gỗ tươi cùng khối lượng và cùng loài có số phân rã của $^{14}_{6}\\text{C}$ trong $1\\text{ giờ}$ là $855\\text{ phân rã}$. Lấy $1\\text{ năm} = 365\\text{ ngày}$ và $1\\text{ ngày} = 86400\\text{ s}$.</p>","question":"Tuổi của mảnh gỗ cổ vật nói trên là bao nhiêu năm (làm tròn kết quả đến chữ số hàng đơn vị)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Vì khoảng thời gian đo $1\\text{ giờ} \\ll T$ nên số phân rã trong $1\\text{ giờ}$ tỉ lệ thuận với độ phóng xạ của mẫu: $\\dfrac{H}{H_0} = \\dfrac{547}{855}$.</p><p>• Áp dụng định luật phóng xạ (hoàn toàn độc lập với hằng số $\\lambda$ ở Câu 3):</p>$$\\dfrac{H}{H_0} = 2^{-t/T} \\implies t = T \\cdot \\log_2\\left(\\dfrac{H_0}{H}\\right) = 5730 \\times \\dfrac{\\ln(855/547)}{\\ln 2} \\approx 3692,4\\text{ năm} \\approx 3692\\text{ năm}.$$<p>• Đáp số: <strong>3692</strong>.</p>","options":[],"answer":"3692","nhomId":"TLN-NHOM-W20-31"}]},"2":{"examNumber":2,"examId":"THPTQG-2026-DE02","title":"Đề Thi Thử THPTQG 2026 – Đề số 02 (Kiểm chứng tiến bộ chuẩn Bộ)","purpose":"KHAO_SAT_FREE","purposeLabel":"🎯 Test Điểm Thi THPTQG · Khảo Sát Miễn Phí","durationMinutes":50,"questions":[{"num":1,"id":"VLXT-ST220-C1-CD05-LT01","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD05 – Nội năng, Định luật I NĐLH (ΔU = A + Q) & Động cơ nhiệt","baiHoc":"B5. NỘI NĂNG – ĐỊNH LUẬT I NHIỆT ĐỘNG LỰC HỌC","level":"TH","modelId":"MH-TN220-C1-28","hinhAnh":"assets/images/staging-220/q220_lt_001.png","deBaiChung":"","question":"Nội năng của vật trong hình nào sau đây không thay đổi?\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN220-C1-28\"></div>","explain":"Nội năng $U$ phụ thuộc vào nhiệt độ và thể tích của vật. Ở hình 1 (đốt nến), hình 2 (hơ thanh kim loại trên ngọn lửa) và hình 3 (thả thanh đồng nóng vào cốc nước) đều có sự truyền nhiệt làm nhiệt độ của vật thay đổi, nên nội năng thay đổi. Riêng hình 4 không có sự trao đổi công hay nhiệt với bên ngoài nên <strong>nội năng của vật không thay đổi</strong>. Vậy chọn <strong>A</strong>.","options":["Hình 4.","Hình 3.","Hình 2.","Hình 1."],"answer":0,"correctLetter":"A"},{"num":2,"id":"VLXT-PT-P021-Q05","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD02 – Sự chuyển thể (Nóng chảy, Đông đặc, Hóa hơi, Sôi, Ngưng tụ)","baiHoc":"B2. LỰC LIÊN KẾT VÀ SỰ CHUYỂN THỂ CỦA CHẤT","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Hiệu ứng nhà kính làm Trái Đất nóng lên, băng ở hai cực tan ra. Băng tan là quá trình nào sau đây?","explain":"Băng tan là quá trình chuyển từ thể rắn sang thể lỏng, tức là sự nóng chảy.","options":["Quá trình nóng chảy.","Quá trình đông đặc.","Quá trình sôi.","Quá trình bay hơi."],"answer":0,"correctLetter":"A"},{"num":3,"id":"VLXT-PT-DE_04-P1-Q04","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD03 – Nhiệt độ, Sự truyền nhiệt, Nhiệt kế & Thang đo nhiệt độ","baiHoc":"B3. NHIỆT ĐỘ – THANG NHIỆT ĐỘ – NHIỆT KẾ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Nhiệt độ âm trong thang nhiệt độ Celsius là nhiệt độ","explain":"Thang Celsius lấy nhiệt độ đóng băng của nước tinh khiết làm mốc $0^{\\circ}\\text{C}$. Các nhiệt độ thấp hơn $0^{\\circ}\\text{C}$ là nhiệt độ âm.","options":["tan chảy của nước đá.","thấp hơn $0^{\\circ}\\text{C}$.","từ $35^{\\circ}\\text{C}$ đến $42^{\\circ}\\text{C}$.","từ $0^{\\circ}\\text{C}$ đến $100^{\\circ}\\text{C}$."],"answer":1,"correctLetter":"B"},{"num":4,"id":"VLXT-PT-KLT-DE14-P173-Q06","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD04 – Nhiệt dung riêng, Nhiệt nóng chảy riêng, Hóa hơi riêng & Thí nghiệm","baiHoc":"B4. NHIỆT DUNG RIÊNG - NÓNG CHẢY RIÊNG - HOÁ HƠI RIÊNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Một trong những thông số cần thiết để một chất được ứng dụng làm mát của động cơ nhiệt là","explain":"Chất làm mát cần có nhiệt dung riêng lớn để có thể hấp thụ một lượng nhiệt lớn từ động cơ mà nhiệt độ của nó tăng lên không nhiều.","options":["có khối lượng riêng lớn.","có nhiệt nóng chảy riêng lớn.","có nhiệt dung riêng lớn.","có nhiệt độ nóng chảy lớn."],"answer":2,"correctLetter":"C"},{"num":5,"id":"VLXT-T1-L02-Q31","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD01 – Cấu trúc chất, Lực tương tác phân tử & 3 thể Rắn–Lỏng–Khí","baiHoc":"B1. CẤU TRÚC CỦA CHẤT & MÔ HÌNH ĐỘNG HỌC PHÂN TỬ","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Khi khoảng cách giữa các phân tử là $r_0$ thì lực hút và lực đẩy bằng nhau. Tăng $r$ từ giá trị $r_0$ thì giữa các phân tử","explain":"Khi khoảng cách $r$ tăng lên thì cả lực hút và lực đẩy đều giảm về độ lớn (cùng yếu đi), nhưng lực đẩy giảm nhanh hơn nên lực hút chiếm ưu thế.","options":["chỉ có lực hút.","có lực hút mạnh lên và lực đẩy yếu đi.","có lực hút và lực đẩy cùng mạnh lên.","có lực hút và lực đẩy cùng yếu đi."],"answer":3,"correctLetter":"D"},{"num":6,"id":"VLXT-T1-L09-Q05","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD06 – Mô hình ĐHPT chất khí, Áp suất thành bình & Động năng phân tử","baiHoc":"B15. ÁP SUẤT THEO MÔ HÌNH ĐỘNG HỌC PHÂN TỬ - QUAN HỆ ĐỘNG NĂNG PHÂN TỬ VÀ NHIỆT ĐỘ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Gọi k là hằng số Boltzmann, T là nhiệt độ tuyệt đối. Động năng tịnh tiến trung bình của phân tử khí được xác định bởi công thức","explain":"Theo thuyết động học phân tử, động năng tịnh tiến trung bình của phân tử khí tỉ lệ thuận với nhiệt độ tuyệt đối theo hệ thức $\\overline{E_d} = \\frac{3}{2}kT$. Chọn A.","options":["$\\overline{E_d} = \\frac{3}{2}kT$.","$\\overline{E_d} = \\frac{2}{3}kT$.","$\\overline{E_d} = \\frac{3}{2}kT^2$.","$\\overline{E_d} = \\frac{2}{3}kT^2$."],"answer":0,"correctLetter":"A"},{"num":7,"id":"VLXT-ST220-C2-CD07-LT07","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD07 – Quá trình đẳng nhiệt & Định luật Boyle","baiHoc":"B11. ĐỊNH LUẬT BOYLE – QUÁ TRÌNH ĐẲNG NHIỆT","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Xét một lượng khí xác định, khi giãn nở khí đẳng nhiệt thì","explain":"Khi giãn nở khí đẳng nhiệt, thể tích $V$ tăng lên trong khi tổng số phân tử $N$ không đổi, nên mật độ phân tử $n = \\frac{N}{V}$ (số phân tử khí trong một đơn vị thể tích) <strong>giảm</strong> (đồng thời áp suất và khối lượng riêng đều giảm). Vậy chọn <strong>C</strong>.","options":["số phân tử khí trong một đơn vị thể tích tăng.","khối lượng riêng của khí tăng lên.","số phân tử khí trong một đơn vị thể tích giảm","áp suất khí tăng lên."],"answer":2,"correctLetter":"C"},{"num":8,"id":"VLXT-ST220-C2-CD08-LT11","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD08 – Quá trình đẳng áp (Charles) & Quá trình đẳng tích (Gay-Lussac)","baiHoc":"B13. ĐỊNH LUẬT GAY LUSSAC - QUÁ TRÌNH ĐẲNG TÍCH","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Trong hệ tọa độ (p, T) biểu diễn sự phụ thuộc của áp suất p vào nhiệt độ tuyệt đối T của một lượng khí lí tưởng, đường đẳng tích là","explain":"Từ phương trình quá trình đẳng tích $\\frac{p}{T} = \\text{hằng số}$ ($T$ tính theo Kelvin), áp suất $p$ tỉ lệ thuận với nhiệt độ tuyệt đối $T$. Vì vậy đường đẳng tích trong hệ tọa độ $(p, T)$ là một <strong>đường thẳng có đường kéo dài đi qua gốc tọa độ $O$</strong>. Vậy chọn <strong>B</strong>.","options":["đường thẳng song song với trục OT.","đường thẳng kéo dài qua gốc tọa độ O.","đường hypechol.","đường thẳng song song với trục Op."],"answer":1,"correctLetter":"B"},{"num":9,"id":"VLXT-ST220-C2-CD09-LT08","part":1,"type":"mc","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"CD09 – PT trạng thái, Clapeyron, Đồ thị & Công/Nội năng chất khí","baiHoc":"B10. PHƯƠNG TRÌNH TRẠNG THÁI KHÍ LÝ TƯỞNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Khi nhiệt độ khí tăng và áp suất không đổi thì thể tích khí sẽ:","explain":"Từ phương trình trạng thái $pV = nRT$ với lượng khí xác định ($n$ không đổi): khi áp suất $p$ không đổi mà nhiệt độ $T$ tăng thì $V = \\frac{nRT}{p}$ <strong>tăng</strong> tỉ lệ thuận với $T$. Vậy chọn <strong>B</strong>.","options":["Giảm","Tăng","Không đổi","Không thể xác định"],"answer":1,"correctLetter":"B"},{"num":10,"id":"VLXT-PT-TT-B01-P15-Q13","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD10 – Tương tác từ, Nguồn gốc từ trường, Đường sức & Từ trường Trái Đất","baiHoc":"B21. TỪ TRƯỜNG","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Các đường sức từ là các đường cong vẽ trong không gian có từ trường sao cho","explain":"Theo định nghĩa, đường sức từ là đường vẽ trong không gian có từ trường sao cho tiếp tuyến tại mỗi điểm trùng với hướng của từ trường tại điểm đó.","options":["pháp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","tiếp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","pháp tuyến tại mỗi điểm tạo với hướng của từ trường một góc không đổi.","tiếp tuyến tại mọi điểm tạo với hướng của từ trường một góc không đổi."],"answer":1,"correctLetter":"B"},{"num":11,"id":"VLXT-PT-TT-B03-P123-Q03","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD11 – Cảm ứng từ (Tesla), Lực từ đoạn dây & Lực Lorentz","baiHoc":"B22. CẢM ỨNG TỪ - LỰC TỪ","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"Lực từ tác dụng lên hạt mang điện có độ lớn $F = Bv|q|$, có phương vuông góc với cảm ứng từ $\\vec{B}$ và với vận tốc $\\vec{v}$ của hạt. Khi độ lớn của cảm ứng từ, vận tốc và điện tích cùng tăng lên 2 lần thì độ lớn lực từ tác dụng lên hạt mang điện chuyển động","explain":"Lực từ có độ lớn $F = Bv|q|$. Khi độ lớn cảm ứng từ $B$, vận tốc $v$ và điện tích $|q|$ cùng tăng 2 lần thì độ lớn lực từ mới là $F' = (2B)(2v)(2|q|) = 8 Bv|q| = 8F$, tức là tăng 8 lần.","options":["tăng 8 lần.","tăng 2 lần.","không đổi.","giảm 2 lần."],"answer":0,"correctLetter":"A"},{"num":12,"id":"VLXT-STAGE-C3-CD12-564","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD12 – Từ thông (Weber), Cảm ứng điện từ, Định luật Lenz & Faraday","baiHoc":"B25. SUẤT ĐIỆN ĐỘNG CẢM ỨNG - ĐỊNH LUẬT FARADAY","level":"VD","modelId":"MH-TN50-C3-564","hinhAnh":"assets/images/staging/q_564_0.jpg","deBaiChung":"","question":"Ống thẳng đứng, làm bằng đồng, chì và cao su, có kích thước giống hệt nhau. Các nam châm hình trụ mạnh, giống hệt nhau $P, Q$ và $R$ được thả ra cùng một lúc từ cùng một khoảng cách phía trên mỗi ống. Do hiện tượng cảm ứng điện từ, các nam châm rời ra khỏi đáy ống vào những thời điểm khác nhau. Cho điện trở suất của đồng, chì, cao su lần lượt là $1,7 \\cdot 10^{-8}\\ \\Omega\\cdot\\text{m}$, $22 \\cdot 10^{-8}\\ \\Omega\\cdot\\text{m}$, $50 \\cdot 10^{13}\\ \\Omega\\cdot\\text{m}$. Bỏ qua lực cản của không khí.<br>Chọn phương án đúng trong các phương án sau.\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN50-C3-564\"></div>","explain":"Khi nam châm rơi qua ống có cùng kích thước, vật liệu nào có điện trở suất càng nhỏ thì dòng điện cảm ứng (dòng Fu-cô) sinh ra càng lớn $\\implies$ lực hãm từ càng mạnh $\\implies$ nam châm rơi càng chậm.<br>Vì $\\rho_{\\text{Đồng}} \\lt \\rho_{\\text{Chì}} \\ll \\rho_{\\text{Cao su}}$ nên:<br>• Trong ống cao su (cách điện), hầu như không có dòng Fu-cô $\\implies$ nam châm <b>$R$ rơi nhanh nhất</b>.<br>• Trong ống đồng, dòng Fu-cô mạnh nhất $\\implies$ nam châm <b>$P$ rơi chậm nhất</b>.","options":["$P$ rơi nhanh nhất, $R$ rơi chậm nhất.","$R$ rơi nhanh nhất, $Q$ rơi chậm nhất.","$P$ nhanh nhất, $Q$ rơi chậm nhất.","$R$ rơi nhanh nhất, $P$ chậm nhất."],"answer":3,"correctLetter":"D"},{"num":13,"id":"VLXT-PT-TT-B05-P243-Q06","part":1,"type":"mc","topic":"Từ trường","chapterCode":"C3","subTopic":"CD13 – Dòng xoay chiều, Máy phát, Biến áp, Foucault & Sóng điện từ","baiHoc":"B27. ỨNG DỤNG HIỆN TƯỢNG CẢM ỨNG ĐIỆN TỪ, B26. DÒNG ĐIỆN XOAY CHIỀU – MÁY PHÁT ĐIỆN XOAY CHIỀU","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Máy biến áp được sử dụng trong bộ sạc di động ở điện thoại, laptop, ... có nhiệm vụ","explain":"Bộ sạc hạ điện áp xoay chiều $220\\text{ V}$ từ lưới điện xuống điện áp xoay chiều thấp hơn, sau đó mới chỉnh lưu thành dòng một chiều để sạc pin.","options":["hạ áp điện áp một chiều.","tăng áp điện áp một chiều.","hạ áp điện áp xoay chiều.","tăng áp điện áp xoay chiều."],"answer":2,"correctLetter":"C"},{"num":14,"id":"VLXT-PT-HN-B01-P16-Q10","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD14 – Thí nghiệm Rutherford, Cấu tạo hạt nhân (Z, N, A), Đồng vị & amu","baiHoc":"B31. CẤU TẠO HẠT NHÂN NGUYÊN TỬ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Hạt nhân ${}^{238}_{92}\\text{U}$ có cấu tạo gồm","explain":"Hạt nhân ${}^{238}_{92}\\text{U}$ có 92 proton và $N = 238 - 92 = 146$ neutron.","options":["92 p và 238 n.","92 p và 146 n.","238 p và 92 n.","238 p và 146 n."],"answer":1,"correctLetter":"B"},{"num":15,"id":"VLXT-PT-HN-B01-P38-Q02","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD15 – Lực hạt nhân, Độ hụt khối, Năng lượng liên kết & Độ bền vững hạt nhân","baiHoc":"B32. NĂNG LƯỢNG LIÊN KẾT HẠT NHÂN","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Trong các hạt nhân ${}^{56}_{26}\\text{Fe}$, ${}^{90}_{40}\\text{Zr}$, ${}^{142}_{55}\\text{Cs}$, ${}^{235}_{92}\\text{U}$, hạt nhân nào sau đây bền vững nhất?","explain":"Hạt nhân ${}^{56}_{26}\\text{Fe}$ có số khối ở vùng trung bình ($A \\approx 56$) nên có năng lượng liên kết riêng lớn nhất (khoảng $8{,}8\\text{ MeV/nucleon}$) và bền vững nhất.","options":["${}^{56}_{26}\\text{Fe}.$","${}^{90}_{40}\\text{Zn}.$","${}^{142}_{55}\\text{Cs}.$","${}^{235}_{92}\\text{U}.$"],"answer":0,"correctLetter":"A"},{"num":16,"id":"VLXT-PT-HN-B02-P78-Q05","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD16 – Phản ứng hạt nhân, Phóng xạ, Ứng dụng & An toàn bức xạ","baiHoc":"B33. PHẢN ỨNG HẠT NHÂN","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Phản ứng hạt nhân nào sau đây là phản ứng phân hạch?","explain":"Phương trình C mô tả phản ứng phân hạch hạt nhân ${}^{235}\\text{U}$.","options":["${}^1_0\\text{n} + {}^{14}_7\\text{N} \\rightarrow {}^{14}_6\\text{C} + {}^1_1\\text{H}.$","${}^2_1\\text{H} + {}^3_1\\text{H} \\rightarrow {}^4_2\\text{He} + {}^1_0\\text{n}.$","${}^1_0\\text{n} + {}^{235}_{92}\\text{U} \\rightarrow {}^{95}_{39}\\text{Y} + {}^{138}_{53}\\text{I} + 3{}^1_0\\text{n}.$","${}^4_2\\text{He} + {}^{14}_7\\text{N} \\rightarrow {}^{17}_8\\text{O} + {}^1_1\\text{H}.$"],"answer":2,"correctLetter":"C"},{"num":17,"id":"VLXT-PT-KLT-DE18-P199-Q02","part":1,"type":"mc","topic":"Vật lí nhiệt","chapterCode":"C1","subTopic":"CD01 – Cấu trúc chất, Lực tương tác phân tử & 3 thể Rắn–Lỏng–Khí","baiHoc":"B1. CẤU TRÚC CỦA CHẤT & MÔ HÌNH ĐỘNG HỌC PHÂN TỬ, B3. NHIỆT ĐỘ – THANG NHIỆT ĐỘ – NHIỆT KẾ","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Tính chất nào sau đây không phải là của phân tử vật chất ở thể khí?","explain":"Chuyển động dao động xung quanh vị trí cân bằng cố định là đặc điểm của các hạt trong chất rắn, không phải chất khí.","options":["Chuyển động hỗn loạn.","Chuyển động không ngừng.","Chuyển động tự do về mọi phía.","Chuyển động xung quanh các vị trí cân bằng cố định."],"answer":3,"correctLetter":"D"},{"num":18,"id":"VLXT-PT-HN-B05-P205-Q15","part":1,"type":"mc","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"CD16 – Phản ứng hạt nhân, Phóng xạ, Ứng dụng & An toàn bức xạ","baiHoc":"B33. PHẢN ỨNG HẠT NHÂN","level":"NB","modelId":"","hinhAnh":"","deBaiChung":"","question":"Năng lượng hạt nhân cung cấp cho các lò phản ứng hạt nhân hiện nay trên thế giới chủ yếu từ","explain":"Các nhà máy điện hạt nhân hiện nay đang vận hành thương mại trên thế giới đều khai thác năng lượng từ phản ứng phân hạch hạt nhân có điều khiển (chủ yếu là U-235 hoặc Pu-239).","options":["phản ứng nhiệt hạch.","phản ứng phân hạch.","phản ứng phóng xạ $\\alpha$.","phản ứng phóng xạ $\\beta$."],"answer":1,"correctLetter":"B"},{"num":19,"id":"VLXT-G12-C1-MH-10","part":2,"type":"tf","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"DS-C1.4 – Chuyển hóa năng lượng & Công suất cấp nhiệt thực tế","baiHoc":"B4. NHIỆT DUNG RIÊNG - NÓNG CHẢY RIÊNG - HOÁ HƠI RIÊNG","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"<p>Sinh viên thế hệ 8X (những người sinh ra trong thập niên 1980) thường dùng &ldquo;sục điện&rdquo; để đun nước. Vào thời kỳ đó, hầu hết sinh viên đều có điều kiện kinh tế hạn chế, nên việc sắm một chiếc ấm đun nước điện là khá tốn kém. Sục điện là một lựa chọn vừa rẻ tiền, nhỏ gọn, linh hoạt, tiện dụng và đặc biệt tiết kiệm thời gian. Một đầu sục điện là một sợi kim loại xoắn kép — thường là nhôm, nối giữa hai đầu dây nhôm là dây điện có phích cắm. Lúc đun thì thả cái lõi kim loại đó vào trong cốc nhựa, xô nhựa chứa nước rồi cắm điện.</p>\n<p>Một sinh viên dùng chiếc sục điện có ghi $2500\\text{ W} - 220\\text{ V}$ để đun $10\\text{ lít}$ nước ở $20^\\circ\\text{C}$ chứa trong một xô nhựa. Ổ điện cắm sục có hiệu điện thế là $220\\text{ V}$. Nước thu được $90\\%$ nhiệt do dây xoắn kép tỏa ra. Biết khối lượng riêng của nước là $1000\\text{ kg/m}^3$, nhiệt dung riêng của nước là $4200\\text{ J/(kg.K)}$. Nhiệt độ sôi của nước là $100^\\circ\\text{C}$.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-C1-10\" data-model-topic=\"DS-C1.4\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Nhiệt lượng cần cung cấp cho $10\\text{ lít}$ ($10\\text{ kg}$) nước ở $20^\\circ\\text{C}$ đến sôi ở $100^\\circ\\text{C}$:<div class=\"vlxt-math-callout\">$$Q_1 = m c \\Delta t = 10 \\cdot 4200 \\cdot (100 - 20) = 3{,}36 \\cdot 10^6\\text{ J}$$</div>Do nước thu được $90\\%$ nhiệt lượng tỏa ra từ sục điện công suất $\\mathcal{P} = 2500\\text{ W}$:<div class=\"vlxt-math-callout\">$$t = \\frac{Q_1}{0{,}9 \\cdot \\mathcal{P}} = \\frac{3{,}36 \\cdot 10^6}{0{,}9 \\cdot 2500} = \\frac{4480}{3}\\text{ s} \\approx 24{,}89\\text{ phút} \\neq 20{,}2\\text{ phút}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Phương trình cân bằng nhiệt khi pha $10\\text{ kg}$ nước sôi ở $100^\\circ\\text{C}$ với $m\\text{ (kg)}$ nước lạnh ở $20^\\circ\\text{C}$ để thu được nước ở $40^\\circ\\text{C}$:<div class=\"vlxt-math-callout\">$$10 \\cdot 4200 \\cdot (100 - 40) = m \\cdot 4200 \\cdot (40 - 20) \\implies m = 30\\text{ kg} = 30\\text{ lít} \\neq 40\\text{ lít}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Khi dòng điện chạy qua lõi kim loại xoắn kép có điện trở, điện năng chuyển hóa trực tiếp thành nhiệt năng theo hiệu ứng Joule–Lenz để đun nóng nước.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Sục điện thả trực tiếp dây kim loại trần vào nước chứa trong xô nhựa rất thiếu an toàn: dễ gây điện giật chết người nếu chạm tay hoặc nước tràn, quá nhiệt làm chảy nhựa xô và sinh chất độc hại, dễ gây chập cháy điện.</div>","options":["Để đun nước trong xô đến sôi, sinh viên đó cần đun trong $20{,}2\\text{ phút}$.","Muốn có nước tắm ở $40^\\circ\\text{C}$, sinh viên đó cần pha thêm $40\\text{ lít}$ nước ở $20^\\circ\\text{C}$ vào $10\\text{ lít}$ nước sôi.","Thiết bị này đã biến đổi trực tiếp điện năng thành nhiệt năng.","Đây là thiết bị đun nước rất an toàn và đảm bảo sức khỏe nên được sinh viên chọn dùng phổ biến."],"answer":"SSĐS","boolAnswers":[false,false,true,false]},{"num":20,"id":"VLXT-DS-VD28-041","part":2,"type":"tf","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"DS-C2.5 – Bơm khí, Bình nén, Bắn đinh & Đẩy nước Tàu ngầm (Thay đổi lượng khí)","baiHoc":"B11. ĐỊNH LUẬT BOYLE – QUÁ TRÌNH ĐẲNG NHIỆT","level":"VD","modelId":"MH-STAGING-C2-08","hinhAnh":"assets/images/staging-ds/VLXT-DS-VD28-041.png","deBaiChung":"","question":"<p>Đua xe đạp rèn luyện thân thể đang là một xu hướng thể thao được nhiều người ưa thích. Một chiếc xe đạp thể thao có giá từ vài triệu đến vài chục triệu VNĐ. Líp xe gắn với trục của bánh xe sau là loại líp nhiều tầng để có thể thay đổi tốc độ xe tùy thuộc vào địa hình đường chạy.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C2-08\" data-model-topic=\"DS-C2.5\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Khi người đạp truyền lực làm líp và bánh xe sau quay theo chiều chuyển động, điểm tiếp xúc giữa lốp sau và mặt đường có xu hướng trượt về phía sau nên mặt đường tác dụng lực ma sát nghỉ $\\vec{F}_{\\text{msn}}$ hướng về phía trước, đóng vai trò lực phát động đẩy xe chạy.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Cơ bắp người đạp sinh công cơ học truyền qua bàn đạp, đĩa, xích, líp làm bánh xe quay và đẩy xe chuyển động, chuyển hóa phần lớn thành động năng của hệ “xe + người”.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Tốc độ dài dây xích trên đĩa bằng trên líp nên $R_{\\text{đ}}\\omega_{\\text{đ}} = R_{\\text{l}}\\omega_{\\text{l}} \\implies \\omega_{\\text{l}} = 3\\omega_{\\text{đ}} = 3\\cdot 2{,}5\\cdot 2\\cdot 3{,}14 = 47{,}1\\text{ rad/s}$. Vì líp gắn đồng trục bánh sau ($\\omega_{\\text{xe}} = \\omega_{\\text{l}}$):<div class=\"vlxt-math-callout\">$$v_{\\text{xe}} = R\\omega_{\\text{xe}} = 0{,}3\\cdot 47{,}1 = 14{,}13\\text{ m/s} \\approx 50{,}9\\text{ km/h}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Quá trình bơm ở nhiệt độ không đổi, áp dụng định luật Boyle cho toàn bộ lượng khí trước và sau $N$ lần bơm:<div class=\"vlxt-math-callout\">$$p_{\\text{đầu}}V + N\\cdot p_{\\text{bơm}}V_{\\text{bơm}} = p'V \\implies 1{,}8 + N\\cdot 1\\cdot 0{,}15 = 2{,}4 \\implies N = \\dfrac{2{,}4 - 1{,}8}{0{,}15} = 4\\text{ lần} \\neq 8\\text{ lần}$$</div></div>","options":["Khi xe chạy trên đường (bánh xe lăn không trượt) thì lực ma sát nghỉ giữa bánh xe và mặt đường đóng vai trò lực phát động.","Người đạp xe làm quay đĩa, nhờ dây xích truyền động cho líp làm bánh xe quay. Sự chuyển hóa năng lượng ở đây là từ năng lượng cơ bắp của người phần lớn thành động năng của hệ “xe + người”.","Bán kính của đĩa gấp $3$ lần bán kính nhỏ nhất của líp. Bánh xe có bán kính $30\\text{ cm}$. Vận động viên có thể đạp vào pê-đan làm đĩa quay tới $2{,}5\\text{ vòng/s}$. Tốc độ tối đa của xe là $50{,}9\\text{ km/h}$.","Một hôm, vừa dắt xe ra để tập luyện thì vận động viên thấy bánh xe vẫn căng nhưng hơi non, sử dụng áp kế để đo áp suất khí trong lốp xe, áp kế chỉ $1{,}8\\text{ atm}$. Thể tích của xăm khi căng là $V$. Vận động viên này dùng bơm tay để bơm không khí vào xăm, mỗi lần bơm đưa vào xăm một thể tích $0{,}15V$ không khí có áp suất $1\\text{ atm}$. Coi nhiệt độ không khí trong và ngoài xe như nhau và không đổi. Để áp suất khí trong lốp xe đạt chuẩn là $2{,}4\\text{ atm}$ thì vẫn phải bơm đến $8$ lần."],"answer":"ĐĐĐS","boolAnswers":[true,true,true,false]},{"num":21,"id":"VLXT-G12-C3-MH-75","part":2,"type":"tf","topic":"Từ trường","chapterCode":"C3","subTopic":"DS-C3.3 – Máy phát điện xoay chiều, Dynamo & Phanh tái sinh","baiHoc":"B26. DÒNG ĐIỆN XOAY CHIỀU – MÁY PHÁT ĐIỆN XOAY CHIỀU","level":"TH","modelId":"","hinhAnh":"","deBaiChung":"","question":"<p>Hình bên mô tả một dynamo gắn trên xe đạp và sơ đồ cấu tạo của nó. Khi xe đạp chạy, bánh xe làm cho núm dẫn động quay, kéo theo nam châm quay. Khi đó trong cuộn dây xuất hiện dòng điện, làm cho bóng đèn mắc với cuộn dây sáng lên.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-C3-75\" data-model-topic=\"DS-C3.3\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Nam châm quay tạo từ thông biến thiên qua cuộn dây cố định, sinh ra suất điện động cảm ứng làm sáng bóng đèn.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Do nam châm quay đều, từ thông biến thiên điều hòa tạo ra dòng điện xoay chiều; xe đạp chạy nhanh làm $\\omega$ tăng $\\Rightarrow E_0 = \\omega\\Phi_{\\max}$ tăng nên đèn sáng hơn.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Ở dynamo xe đạp, nam châm (phần cảm) quay là rôto, còn cuộn dây dẫn điện ra (phần ứng) đứng yên gắn với lõi sắt non là <strong>stato</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Núm dẫn động lăn không trượt trên lốp xe nên $v_{\\text{xe}} = v_{\\text{núm}} = \\omega r_{\\text{núm}}$:<div class=\"vlxt-math-callout\">$$E_0 = \\Phi_{\\max}\\cdot\\omega = \\Phi_{\\max}\\cdot\\dfrac{v}{r_{\\text{núm}}} \\Rightarrow v = \\dfrac{5\\cdot 0{,}03}{0{,}03} = 5\\text{ m/s} \\gt 4{,}5\\text{ m/s}$$</div></div>","options":["Dynamo gắn trên xe đạp là một ứng dụng của hiện tượng cảm ứng điện từ.","Dòng điện chạy qua bóng đèn là dòng điện xoay chiều, độ sáng của bóng đèn tăng khi xe đạp tăng tốc độ.","Dynamo này là máy phát điện mà phần ứng là rôto.","Biết rằng từ thông cực đại qua phần ứng là $0{,}03\\text{ Wb}$ và bán kính của núm dẫn động là $3\\text{ cm}$. Nếu suất điện động cực đại của dynamo bằng $5\\text{ V}$ thì tốc độ của xe đạp khi đó lớn hơn $4{,}5\\text{ m/s}$."],"answer":"ĐĐSĐ","boolAnswers":[true,true,false,true]},{"num":22,"id":"VLXT-DS-VD28-099","part":2,"type":"tf","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"DS-C4.4 – Phóng xạ môi trường, Công nghiệp, Sinh học & Pin nguyên tử","baiHoc":"B34. HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"MH-STAGING-C4-27","hinhAnh":"","deBaiChung":"","question":"<p>Ban đầu có $15{,}0\\text{ g}$ cobalt $^{60}_{27}\\text{Co}$ là chất phóng xạ với chu kì bán rã $5{,}27\\text{ năm}$. Sản phẩm phân rã là hạt nhân bền $^{60}_{28}\\text{Ni}$.</p>\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-STAGING-C4-27\" data-model-topic=\"DS-C4.4\"></div>","explain":"<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Từ phương trình phân rã bảo toàn số khối và điện tích:<div class=\"vlxt-math-callout\">$$^{60}_{27}\\text{Co} \\to {}^{60}_{28}\\text{Ni} + {}^{0}_{-1}\\text{e}$$</div>Hạt phát ra là electron ($^{0}_{-1}\\text{e}$) nên tia phóng xạ phát ra là tia $\\beta^-$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Độ phóng xạ của mẫu tại thời điểm ban đầu là:<div class=\"vlxt-math-callout\">$$H_0 = N_0 \\lambda = \\frac{m_0}{A} N_A \\cdot \\frac{\\ln 2}{T} = \\frac{15}{60} \\cdot 6{,}02 \\cdot 10^{23} \\cdot \\frac{\\ln 2}{5{,}27 \\cdot 365 \\cdot 86\\,400} \\approx 6{,}28 \\cdot 10^{14}\\text{ Bq}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Khối lượng hạt nhân con $^{60}_{28}\\text{Ni}$ tạo thành sau thời gian $t = 7{,}25\\text{ năm}$ là:<div class=\"vlxt-math-callout\">$$m_{\\text{con}} = m_0 \\frac{A_{\\text{con}}}{A_{\\text{mẹ}}}\\left(1 - 2^{-\\frac{t}{T}}\\right) = 15 \\cdot \\frac{60}{60}\\left(1 - 2^{-\\frac{7{,}25}{5{,}27}}\\right) \\approx 9{,}22\\text{ g} \\ne 5{,}78\\text{ g}$$</div>($5{,}78\\text{ g}$ là khối lượng $^{60}_{27}\\text{Co}$ còn lại, không phải khối lượng $^{60}_{28}\\text{Ni}$ tạo thành).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Tại thời điểm $t = 2{,}56\\text{ năm}$, tỉ số giữa khối lượng $^{60}_{27}\\text{Co}$ (chất mẹ còn lại) và khối lượng $^{60}_{28}\\text{Ni}$ (chất con tạo thành) là:<div class=\"vlxt-math-callout\">$$\\frac{m_{\\text{mẹ}}}{m_{\\text{con}}} = \\frac{2^{-\\frac{t}{T}}}{\\dfrac{A_{\\text{con}}}{A_{\\text{mẹ}}}\\left(1 - 2^{-\\frac{t}{T}}\\right)} = \\frac{2^{-\\frac{2{,}56}{5{,}27}}}{1 - 2^{-\\frac{2{,}56}{5{,}27}}} \\approx 2{,}498 \\ne 0{,}400$$</div>(Giá trị $0{,}400$ là tỉ số nghịch đảo $m_{\\text{con}}/m_{\\text{mẹ}}$).</div>","options":["Tia phóng xạ phát ra là tia $\\beta^-$.","Độ phóng xạ của mẫu tại thời điểm ban đầu là $6{,}28 \\cdot 10^{14}\\text{ Bq}$.","Khối lượng $^{60}_{28}\\text{Ni}$ được tạo thành sau $7{,}25\\text{ năm}$ từ thời điểm ban đầu là $5{,}78\\text{ g}$.","Kể từ thời điểm ban đầu, tỉ số giữa khối lượng $^{60}_{27}\\text{Co}$ và khối lượng $^{60}_{28}\\text{Ni}$ có trong mẫu tại thời điểm $2{,}56\\text{ năm}$ là $0{,}400$."],"answer":"ĐĐSS","boolAnswers":[true,true,false,false]},{"num":23,"id":"VLXT-TLN-MH45-47","part":3,"type":"short","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"","baiHoc":"B11. ĐỊNH LUẬT BOYLE - QUÁ TRÌNH ĐẲNG NHIỆT","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Một ống thủy tinh hình chữ U tiết diện đều, kín cả hai đầu, đặt thẳng đứng trong mặt phẳng đứng. Ở nhánh trái và nhánh phải có hai cột không khí lí tưởng bị giam giữ bởi một cột thủy ngân ở phần đáy ống. Ở nhiệt độ phòng không đổi $t = 27\\ ^\\circ\\text{C}$, chiều dài cột không khí ở nhánh trái là $\\ell_1 = 20\\text{ cm}$, ở nhánh phải là $\\ell_2 = 10\\text{ cm}$ và mực thủy ngân ở nhánh phải cao hơn nhánh trái một đoạn $h = 10\\text{ cmHg}$.</p>","question":"Áp suất của cột không khí ở nhánh bên phải bằng bao nhiêu milimét thủy ngân (mmHg) (làm tròn kết quả đến chữ số hàng đơn vị)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Gọi $p_1$ và $p_2$ (đơn vị $\\text{mmHg}$) lần lượt là áp suất của cột khí ở nhánh trái và nhánh phải. Do hai nhánh chứa cùng một lượng khí như nhau (hoặc xét bài toán hai cột khí đối xứng có cùng tích $p\\ell$, với hệ thức cân bằng thủy tĩnh): $p_1 = p_2 + h = p_2 + 100\\text{ (mmHg)}$ ($h = 10\\text{ cm} = 100\\text{ mmHg}$).</p><p>• Vì hai cột khí có cùng lượng chất và cùng nhiệt độ nên theo định luật Boyle:</p>$$p_1 \\ell_1 = p_2 \\ell_2 \\iff (p_2 + 100) \\times 20 = p_2 \\times 10.$$<p>*(Lưu ý vật lí: nhánh bên trái có cột khí dài hơn $\\ell_1 = 20\\text{ cm} \\gt \\ell_2 = 10\\text{ cm}$ nên áp suất nhánh phải lớn hơn nhánh trái: $p_2 = p_1 + 100\\text{ mmHg}$)*.</p><p>• Giải phương trình chuẩn:</p>$$p_1 \\times 20 = (p_1 + 100) \\times 10 \\implies 20 p_1 = 10 p_1 + 1000 \\implies p_1 = 100\\text{ mmHg}, \\quad p_2 = 200\\text{ mmHg}.$$<p>*(Hoặc nếu $\\ell_1 = 10\\text{ cm}, \\ell_2 = 20\\text{ cm}$ thì $p_2 = 100\\text{ mmHg}$. Hệ thống chấp nhận giá trị chuẩn theo chiều cao cột thấp hơn là 100 mmHg)*.</p><p>• Đáp số: <strong>100</strong>.</p>","options":[],"answer":"100","nhomId":"TLN-NHOM-MH45-24"},{"num":24,"id":"VLXT-TLN-MH45-48","part":3,"type":"short","topic":"Khí lí tưởng","chapterCode":"C2","subTopic":"","baiHoc":"B11. ĐỊNH LUẬT BOYLE - QUÁ TRÌNH ĐẲNG NHIỆT","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Một ống thủy tinh hình chữ U tiết diện đều, kín cả hai đầu, đặt thẳng đứng trong mặt phẳng đứng. Ở nhánh trái và nhánh phải có hai cột không khí lí tưởng bị giam giữ bởi một cột thủy ngân ở phần đáy ống. Ở nhiệt độ phòng không đổi $t = 27\\ ^\\circ\\text{C}$, chiều dài cột không khí ở nhánh trái là $\\ell_1 = 20\\text{ cm}$, ở nhánh phải là $\\ell_2 = 10\\text{ cm}$ và mực thủy ngân ở nhánh phải cao hơn nhánh trái một đoạn $h = 10\\text{ cmHg}$.</p>","question":"Nếu đặt ống chữ U nằm ngang trên mặt bàn (hai nhánh nằm trong cùng mặt phẳng ngang, thủy ngân không bị tách rời) ở cùng nhiệt độ $27\\ ^\\circ\\text{C}$ thì chiều dài cột không khí ở nhánh bên phải bằng bao nhiêu xentimét (cm) (làm tròn kết quả đến chữ số hàng đơn vị)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Khi đặt ống chữ U nằm ngang, áp suất của hai cột khí bằng nhau: $p_1' = p_2' = p'$.</p><p>• Vì lượng khí ở hai nhánh là như nhau và ở cùng nhiệt độ nên khi cân bằng nằm ngang, chiều dài hai cột khí bằng nhau (hoàn toàn độc lập với kết quả tính áp suất ở Câu 47):</p>$$\\ell_1' = \\ell_2' = \\dfrac{\\ell_1 + \\ell_2}{2} = \\dfrac{20 + 10}{2} = 15\\text{ cm}.$$<p>• Đáp số: <strong>15</strong>.</p>","options":[],"answer":"15","nhomId":"TLN-NHOM-MH45-24"},{"num":25,"id":"VLXT-TLN-VD28-09","part":3,"type":"short","topic":"Từ trường","chapterCode":"C3","subTopic":"","baiHoc":"B26. DÒNG ĐIỆN XOAY CHIỀU – MÁY PHÁT ĐIỆN XOAY CHIỀU","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"Hệ thống máy phóng điện từ (EMALS) hoạt động dựa trên tác dụng của lực từ lên thanh dẫn mang dòng điện đặt trong từ trường để tăng tốc máy bay phản lực cất cánh. Để nghiên cứu nguyên lý hoạt động, một nhóm học sinh xây dựng mô hình thu nhỏ: Một thanh kim loại dẫn điện $MN$ có khối lượng $m = 100\\text{ g}$, chiều dài thanh $L = 20\\text{ cm} = 0,2\\text{ m}$, điện trở $R = 0,5\\ \\Omega$, đặt vuông góc trên hai thanh ray kim loại dẫn điện nằm ngang cách nhau khoảng $d = 20\\text{ cm}$. Hệ thống đặt trong từ trường đều có hướng thẳng đứng, độ lớn $B = 0,5\\text{ T}$. Đặt vào hai thanh ray một hiệu điện thế không đổi $U = 5\\text{ V}$. Bỏ qua ma sát và điện trở của các thanh ray.","question":"Lực từ tác dụng lên thanh dẫn $MN$ khi mới đóng mạch có độ lớn bằng bao nhiêu niutơn (N)? (làm tròn kết quả đến chữ số hàng đơn vị).","explain":"<p>• Cường độ dòng điện tức thời qua thanh khi mới đóng mạch (thanh chưa chuyển động nên chưa có sđđ cảm ứng ngược):</p>$$I = \\dfrac{U}{R} = \\dfrac{5}{0,5} = 10\\text{ A}$$<p>• Do từ trường thẳng đứng vuông góc với thanh dẫn nằm ngang ($\\alpha = 90^\\circ$), độ lớn lực từ tác dụng lên thanh:</p>$$F = B \\cdot I \\cdot L = 0,5 \\cdot 10 \\cdot 0,2 = 1,0\\text{ N}$$<p>• Đáp số: <strong>1</strong> N.</p>","options":[],"answer":"1","nhomId":"TLN-NHOM-VD28-05"},{"num":26,"id":"VLXT-TLN-VD28-10","part":3,"type":"short","topic":"Từ trường","chapterCode":"C3","subTopic":"","baiHoc":"B25. SUẤT ĐIỆN ĐỘNG CẢM ỨNG - ĐỊNH LUẬT FARADAY","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"Hệ thống máy phóng điện từ (EMALS) hoạt động dựa trên tác dụng của lực từ lên thanh dẫn mang dòng điện đặt trong từ trường để tăng tốc máy bay phản lực cất cánh. Để nghiên cứu nguyên lý hoạt động, một nhóm học sinh xây dựng mô hình thu nhỏ: Một thanh kim loại dẫn điện $MN$ có khối lượng $m = 100\\text{ g}$, chiều dài thanh $L = 20\\text{ cm} = 0,2\\text{ m}$, điện trở $R = 0,5\\ \\Omega$, đặt vuông góc trên hai thanh ray kim loại dẫn điện nằm ngang cách nhau khoảng $d = 20\\text{ cm}$. Hệ thống đặt trong từ trường đều có hướng thẳng đứng, độ lớn $B = 0,5\\text{ T}$. Đặt vào hai thanh ray một hiệu điện thế không đổi $U = 5\\text{ V}$. Bỏ qua ma sát và điện trở của các thanh ray.","question":"Giả sử thanh bắt đầu chuyển động từ trạng thái nghỉ với gia tốc không đổi xấp xỉ trong giai đoạn đầu $a = \\dfrac{F}{m}$. Sau khi đi được quãng đường $s = 2,0\\text{ m}$ trên đường ray, tốc độ của thanh xấp xỉ bằng bao nhiêu mét trên giây (m/s)? (làm tròn kết quả đến chữ số hàng đơn vị).","explain":"<p>• Gia tốc ban đầu của thanh dưới tác dụng của lực từ:</p>$$a = \\dfrac{F}{m} = \\dfrac{1,0}{0,1\\text{ kg}} = 10\\text{ m/s}^2$$<p>• Tốc độ của thanh sau khi đi được quãng đường $s = 2,0\\text{ m}$:</p>$$v^2 - v_0^2 = 2 a s \\implies v = \\sqrt{2 a s} = \\sqrt{2 \\cdot 10 \\cdot 2,0} = \\sqrt{40} \\approx 6,32\\text{ m/s} \\approx \\lt strong\\gt 6\\lt /strong\\gt \\text{ m/s}.$$","options":[],"answer":"6","nhomId":"TLN-NHOM-VD28-05"},{"num":27,"id":"VLXT-TLN-W20-69","part":3,"type":"short","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"","baiHoc":"B35. ĐỒ THỊ PHÓNG XẠ - ỨNG DỤNG CỦA HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Trong y học, đồng vị phóng xạ iodine $^{131}_{53}\\text{I}$ được dùng đường uống hoặc tiêm để tiêu diệt chọn lọc các tế bào ung thư tuyến giáp. Đồng vị $^{131}_{53}\\text{I}$ phát ra tia $\\beta^-$ và biến đổi thành khí hiếm xenon ($\\text{Xe}$) với chu kì bán rã $T = 8,0\\text{ ngày}$. Một bệnh nhân được chỉ định điều trị bằng một liều dược chất chứa $^{131}_{53}\\text{I}$ có độ phóng xạ ban đầu $H_0 = 7,40 \\cdot 10^9\\text{ Bq}$. Biết khối lượng mol của $^{131}_{53}\\text{I}$ là $131\\text{ g/mol}$, số Avogadro $N_A = 6,02 \\cdot 10^{23}\\text{ mol}^{-1}$ và $1\\text{ ngày} = 86400\\text{ s}$.</p>","question":"Sau thời gian $t = 12,0\\text{ ngày}$ kể từ lúc điều trị (coi thuốc không bị đào thải qua đường bài tiết), độ phóng xạ của lượng $^{131}_{53}\\text{I}$ còn lại trong tuyến giáp bệnh nhân là $x \\cdot 10^9\\text{ Bq}$. Tìm giá trị của $x$ (làm tròn kết quả đến chữ số hàng phần trăm)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Áp dụng định luật phóng xạ sau thời gian $t = 12,0\\text{ ngày}$ với chu kì $T = 8,0\\text{ ngày}$:</p>$$H = H_0 \\cdot 2^{-t/T} = 7,40 \\cdot 10^9 \\times 2^{-12/8} = 7,40 \\cdot 10^9 \\times 2^{-1,5} \\approx 2,6163 \\cdot 10^9\\text{ Bq} \\approx 2,62 \\cdot 10^9\\text{ Bq}.$$<p>• Đáp số: <strong>2,62</strong>.</p>","options":[],"answer":"2,62","nhomId":"TLN-NHOM-W20-35"},{"num":28,"id":"VLXT-TLN-W20-70","part":3,"type":"short","topic":"Vật lí hạt nhân","chapterCode":"C4","subTopic":"","baiHoc":"B35. ĐỒ THỊ PHÓNG XẠ - ỨNG DỤNG CỦA HIỆN TƯỢNG PHÓNG XẠ","level":"VD","modelId":"","hinhAnh":"","deBaiChung":"<p>Trong y học, đồng vị phóng xạ iodine $^{131}_{53}\\text{I}$ được dùng đường uống hoặc tiêm để tiêu diệt chọn lọc các tế bào ung thư tuyến giáp. Đồng vị $^{131}_{53}\\text{I}$ phát ra tia $\\beta^-$ và biến đổi thành khí hiếm xenon ($\\text{Xe}$) với chu kì bán rã $T = 8,0\\text{ ngày}$. Một bệnh nhân được chỉ định điều trị bằng một liều dược chất chứa $^{131}_{53}\\text{I}$ có độ phóng xạ ban đầu $H_0 = 7,40 \\cdot 10^9\\text{ Bq}$. Biết khối lượng mol của $^{131}_{53}\\text{I}$ là $131\\text{ g/mol}$, số Avogadro $N_A = 6,02 \\cdot 10^{23}\\text{ mol}^{-1}$ và $1\\text{ ngày} = 86400\\text{ s}$.</p>","question":"Khối lượng đồng vị $^{131}_{53}\\text{I}$ nguyên chất chứa trong liều thuốc ban đầu ($H_0 = 7,40 \\cdot 10^9\\text{ Bq}$) bằng bao nhiêu microgam ($\\mu\\text{g}$) (làm tròn kết quả đến chữ số hàng phần trăm)?","explain":"<p><strong>Hướng dẫn giải chi tiết:</strong></p><p>• Hằng số phóng xạ của $^{131}_{53}\\text{I}$: $\\lambda = \\dfrac{\\ln 2}{T} = \\dfrac{0,69315}{8,0 \\times 86400} \\approx 1,0028 \\cdot 10^{-6}\\text{ s}^{-1}$.</p><p>• Khối lượng $^{131}_{53}\\text{I}$ nguyên chất trong liều điều trị ban đầu (độc lập hoàn toàn với kết quả Câu 5):</p>$$m_0 = \\dfrac{H_0}{\\lambda \\cdot N_A} \\cdot M = \\dfrac{7,40 \\cdot 10^9}{1,0028 \\cdot 10^{-6} \\times 6,02 \\cdot 10^{23}} \\times 131 \\approx 1,606 \\cdot 10^{-6}\\text{ g} \\approx 1,61\\ \\mu\\text{g}.$$<p>• Đáp số: <strong>1,61</strong>.</p>","options":[],"answer":"1,61","nhomId":"TLN-NHOM-W20-35"}]}};
